import re


class FastPassOutput:
    ARTIFACT_COMMON_PATTERN = (r'\s+Build\s+Number:\s+(?P<build_number>\S+)'
                               r'(?:\s+Introduced\s+By:\s+(?P<introduced_by>\S+))?'
                               r'(?:\s+Last\s+Deployed\s+With:\s+(?P<last_deployed_with>\S+))?'
                               r'(?:\s+File\s+Name:\s+(?P<file_name>\S+))?'
                               r'(?:\s+Size:\s+(?P<size>.+))?')
    STATUS_PATTERN = r'\s+Status:\s+(?P<status>.+)'
    STATUS_VALUES_PATTERN = r'(?:SKIPP?ED|(?:NOT[\s_])?DEPLOY(?:ED|ING))'

    def __init__(self, stdout, flags=None, options=None):
        self.text = stdout
        self.flags = flags or []
        self.options = options or {}
        self._structure = None

    @property
    def structure(self):
        if not self._structure:
            self._convert()
        return self._structure

    def _convert(self):
        if self.options['--artifact']:
            self._convert_to_structure_1()
        elif self.options['--fp']:
            self._convert_to_structure_2()
        elif '--all' in self.flags or self.options['--latest']:
            self._convert_to_structure_3()
        elif '--list' in self.flags:
            self._convert_to_structure_4()

    def _convert_to_structure_1(self):
        artifact_pattern = r'\s+Artifact\s+ID:\s+(?P<artifact_id>\S+)'
        pattern = re.compile(artifact_pattern + self.ARTIFACT_COMMON_PATTERN + self.STATUS_PATTERN)
        artifact_items_match = pattern.search(self.text)
        if artifact_items_match:
            self._structure = artifact_items_match.groupdict()
        else:
            self._structure = re.compile(artifact_pattern).search(self.text).groupdict()
            self._structure['last_deployed'] = self._parse_last_deployed()
            self._structure['last_operation'] = self._parse_last_operation()

    def _parse_last_deployed(self):
        ld_pattern = re.compile(r'Last\s+Deployed:'
                                r'(?:(?:\s+.+:.+)+|\s+(?P<rc>.+))', re.I)
        ld_match = ld_pattern.search(self.text)
        if ld_match:
            pattern = re.compile(self.ARTIFACT_COMMON_PATTERN)
            return ld_match.groupdict()['rc'] or pattern.search(ld_match.group()).groupdict()

    def _parse_last_operation(self):
        lo_pattern = re.compile(r'Last\s+Operation:'
                                r'(?:(?:\s+.+:.+)+|\s+(?P<rc>.+))', re.I)
        lo_match = lo_pattern.search(self.text)
        if lo_match:
            pattern = re.compile(self.ARTIFACT_COMMON_PATTERN + self.STATUS_PATTERN)
            return lo_match.groupdict()['rc'] or pattern.search(lo_match.group()).groupdict()

    def _convert_to_structure_2(self):
        status_pattern = re.compile(self.STATUS_PATTERN, re.I)
        rc_pattern = re.compile(r'Rollback\sCapability:\s+(?P<rollback_capability>\S+)', re.I)
        rs_item_pattern = r'\s+\d+\.\s+(\S+)'
        rs_pattern = re.compile(rf'Rollback\sSequence:(?:{rs_item_pattern})+', re.I)
        self._structure = status_pattern.search(self.text).groupdict()
        self._structure['sub_packages'] = self._parse_sub_packages()
        self._structure.update(rc_pattern.search(self.text).groupdict())
        rs_match = rs_pattern.search(self.text)
        if rs_match:
            self._structure['rollback_sequence'] = re.compile(rs_item_pattern).findall(rs_match.group())

    def _parse_sub_packages(self):
        sp_pattern = re.compile(rf'Sub-package:\s+(\S+)$'
                                rf'(?:\s+NE:\s+Type:\s+(.+)$\s+Release:\s+(.+)$\s+Description:\s+(.+)$)?'
                                rf'\s+Artifacts:((?:\s+{self.STATUS_VALUES_PATTERN}\s+\S+$)+)',
                                re.M | re.I)
        return [
            {'sub_package': e[0],
             'ne': {'type': e[1],
                    'release': e[2],
                    'description': e[3]} if e[1] else None,
             'artifacts': self._parse_artifacts(e[4])}
            for e in sp_pattern.findall(self.text)
        ]

    def _parse_artifacts(self, text):
        pattern = re.compile(rf'({self.STATUS_VALUES_PATTERN})\s+(\S+)', re.I)
        return [
            {'status': e[0],
             'artifact': e[1]}
            for e in pattern.findall(text)
        ]

    def _convert_to_structure_3(self):
        pattern = re.compile(rf'({self.STATUS_VALUES_PATTERN})\s+(\S+)\s+(\S+)\s+(\S+)')
        self._structure = [
            {'status': e[0],
             'time': e[1],
             'sub_package': e[2],
             'fast_pass_package': e[3]}
            for e in pattern.findall(self.text)
        ]

    def _convert_to_structure_4(self):
        pattern = re.compile(rf'({self.STATUS_VALUES_PATTERN})\s+(\S+)\s+(\S+)')
        self._structure = [
            {'status': e[0],
             'installation_time': e[1],
             'fast_pass_package': e[2]}
            for e in pattern.findall(self.text)]

    def __repr__(self):
        return self.text
